/*
 * Generated by the contentIcons plugin in vite.config.ts.
 * Typed as the full icon set, but a build only includes the icons the content uses.
 */

/** Icons named by `icon:` in the frontmatter of .mdx files */
declare module 'virtual:frontmatter-icons' {
  export * from '@navikt/aksel-icons';
}

/** Icons imported by *.stories.tsx and *.dodont.tsx files */
declare module 'virtual:story-icons' {
  export * from '@navikt/aksel-icons';
}

/** All of '@navikt/aksel-icons', for loading on demand with `import()` */
declare module 'virtual:all-icons' {
  export * from '@navikt/aksel-icons';
}
